---RefreshCellByQuestId 根据关卡id刷新cell
---@param questId integer @ 关卡id
function GachaCoinQuestCellItem:RefreshCellByQuestId(questId)
    local questVo = GCQUtils.GetGachaCoinQuestConfigById(checkInt(questId))
    if not isNull(questVo) then
        -- 关卡名
        self.QuestNameLabel.text = questVo.label

        -- 关卡序号
        self.QuestNoLabel.text = questVo.name

        -- 底色
        local rgbStr = questVo.rgb
        local rgbInfo = parse_strings(rgbStr, ';')
        --self.SplitLine.color = XLuaUtils.HexToColor(rgbInfo[2]) --这两个颜色动态变化
        --self.QuestNoLabel.color = XLuaUtils.HexToColor(rgbInfo[3])
        self.QuestNameLabel.color = XLuaUtils.HexToColor(rgbInfo[3])--这两个颜色不变
        self.Text.color = XLuaUtils.HexToColor(rgbInfo[4])

    else
        print('非法的关卡id')
    end
end

---RefreshCellSelected 刷新关卡是否被选中
---@param isSelected boolean 是否选中
function GachaCoinQuestCellItem:RefreshCellSelected(isSelected)
    KTool.SetActive(self.CellBg.gameObject, isSelected)
    local questVo = GCQUtils.GetGachaCoinQuestConfigById(checkInt(self:GetQuestId()))
    local rgbStr = questVo.rgb
    local rgbInfo = parse_strings(rgbStr, ';')
    self.SplitLine.color = XLuaUtils.HexToColor(isSelected and rgbInfo[2] or defaultNumberColor)
    self.QuestNoLabel.color = XLuaUtils.HexToColor(isSelected and rgbInfo[3] or defaultNumberColor)
    if isSelected then
        self.QuestNameLabel.color = XLuaUtils.HexToColor(rgbInfo[3])
        self.Text.color = XLuaUtils.HexToColor(rgbInfo[4])
        --设置本地数据
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GachaCoinQuestComponent)
        comp:SetCurChallengeLevel(self:GetQuestId())
        self:RefreshCellScale(1)
    else
        self:RefreshCellScale(0.65)
    end
end

---RefreshCellScale 刷新格子的缩放
---@param scale number @ 缩放
function GachaCoinQuestCellItem:RefreshCellScale(scale)
    -- self.controller:GetComponent(typeof(CS.UnityEngine.RectTransform)).localScale = Vector3.New(
    --     scale, scale, 1
    -- )

    --self.LockIcon.gameObject:GetComponent(typeof(RectTransform_)).localScale = Vector3.New(scale, scale, 1)
    self.QuestNoLabel.gameObject:GetComponent(typeof(RectTransform_)).localScale = Vector3.New(scale, scale, 1)
end


